PAGE = dict(
    slug='y_label',
    title='Pane::y_label',
    signature='Pane& Pane::y_label(std::string label)',
    intro="Sets the label of the y axis: the text drawn beside the axis that says what it measures. It is separate from the pane's own title ([`Pane::title`](title.md), drawn above the whole plot) and from the shared caption of an alignment group ([`Studio::y_caption`](../studio/y_caption.md), drawn once for several panes); the three can be used together. The text is stored in `y_axis().label`, where it can be read back; there is no separate getter.\n\nThe setter takes any text. An empty string clears the label and gives exactly the figure that never had one, a second call replaces the first, and text between dollar signs is typeset as math. The label is read when the figure is rendered, so it can be set before or after the traces. Its distance from the axis is [`y_label_gap`](y_label_gap.md) and its angle is [`y_label_rotation`](y_label_rotation.md); the axis tick labels are separate ([`y_tick_labels`](y_tick_labels.md)).",
    parameters='**label** (`std::string`)\n    The label text. Empty clears the label.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='basic', text='Setting the y label. The label is stored in `y_axis().label` and drawn beside the y axis.',
             code='auto fig = studio("y_label_basic");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nstd::cout << "before: \'" << pane.y_axis().label << "\'\\n";\npane.y_label("Elapsed time (s)");\nstd::cout << "after: \'" << pane.y_axis().label << "\'\\n";\nstd::cout << "drawn: " << (fig.to_svg().find(">Elapsed time (s)<") != std::string::npos) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='replace_clear', text='Replacing and clearing. A second call replaces the text, and an empty string clears it: the figure is then exactly the figure that never had a label.',
             code='auto build = [&](const char* first, const char* second) {\n  auto fig = studio("y_label_clear");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  if (first) pane.y_label(first);\n  if (second) pane.y_label(second);\n  return fig.to_svg();\n};\nstd::cout << "replaced: " << (build("old", "new").find(">new<") != std::string::npos) << ", old still drawn: " << (build("old", "new").find(">old<") != std::string::npos) << "\\n";\nstd::cout << "cleared == never set: " << (build("temporary", "") == build(nullptr, nullptr)) << "\\n";\nauto fig = studio("y_label_clear_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("Final label");\nfig.save_svg("figure.svg");'),
        dict(id='distinct', text="Not the title and not a shared caption. The pane's title, its y label and a figure-level caption are three separate texts; each is set by its own call and each is drawn in its own place.",
             code='auto fig = studio("y_label_distinct");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.title("Pane title");\npane.y_label("Axis label");\npane.align_y("group");\nfig.y_caption("group", "Shared caption");\nconst std::string svg = fig.to_svg();\nstd::cout << "title: " << (svg.find(">Pane title<") != std::string::npos) << ", label: " << (svg.find(">Axis label<") != std::string::npos) << ", caption: " << (svg.find(">Shared caption<") != std::string::npos) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='independent', text='Per axis. Setting the y label leaves the labels of the other axes empty, and each axis keeps its own text.',
             code='auto fig = studio("y_label_independent");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("this axis only");\nstd::cout << "x: \'" << pane.x_axis().label << "\', y: \'" << pane.y_axis().label << "\', z: \'" << pane.z_axis().label << "\'\\n";\npane.x_label("x text").y_label("y text").z_label("z text");\nstd::cout << "all set: \'" << pane.x_axis().label << "\', \'" << pane.y_axis().label << "\', \'" << pane.z_axis().label << "\'\\n";\nfig.save_svg("figure.svg");'),
        dict(id='math', text='Math text. A label with `$...$` is typeset, so Greek letters and subscripts appear as symbols instead of the raw markup.',
             code='auto fig = studio("y_label_math");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.y_label("$\\\\sigma_t$ (volatility)");\nconst std::string svg = fig.to_svg();\nstd::cout << "raw markup drawn: " << (svg.find("$\\\\sigma_t$") != std::string::npos) << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Not `noexcept`: it moves the text into the pane.\n- The label of an axis does not change the axis range or its ticks.',
    see=['[`Pane::y_label_gap`](y_label_gap.md), [`y_label_rotation`](y_label_rotation.md): where and at what angle it is drawn.', '[`Studio::y_caption`](../studio/y_caption.md): one caption shared by aligned panes.', '[`Pane::title`](title.md): the title of the pane.', '[`Pane::x_label`](x_label.md): the same setting for the x axis.', '[`Pane::z_label`](z_label.md): the same setting for the z axis.'],
)
